// CloudtainerML rev0029 — Spectral/operator routing hardening probe.
// Actual tiny transforms instead of only symbolic routing scores. Not a CHIAR reproduction.
#include <bits/stdc++.h>
using namespace std;
static string q(const string&s){string o="\""; for(char c:s){ if(c=='"'||c=='\\') o+='\\'; if(c=='\n') o+="\\n"; else o+=c;} return o+'"';}
static double PI=acos(-1.0);
struct Regime{string name; double low, high, local, sparse, noise, alias, natural; int seed;};
struct Row{string regime, method; int n,budget_pct,k; double target,out,abs_error,cost_frac,budget_over,alias_error,tail_miss,regret,score;};
static vector<double> dct_coeff(const vector<double>&x){int N=x.size(); vector<double> c(N); double s0=sqrt(1.0/N), s=sqrt(2.0/N); for(int k=0;k<N;k++){double sum=0; for(int n=0;n<N;n++) sum += x[n]*cos(PI*(n+0.5)*k/N); c[k]=sum*(k==0?s0:s);} return c;}
static vector<double> idct_from(const vector<double>&c, const vector<int>&keep){int N=c.size(); vector<char> mask(N,0); for(int k:keep) if(0<=k&&k<N) mask[k]=1; vector<double> x(N); double s0=sqrt(1.0/N), s=sqrt(2.0/N); for(int n=0;n<N;n++){double sum=0; for(int k=0;k<N;k++) if(mask[k]) sum += c[k]*(k==0?s0:s)*cos(PI*(n+0.5)*k/N); x[n]=sum;} return x;}
static vector<double> softmax_masked(const vector<double>&logits, const vector<char>&mask){int N=logits.size(); double mx=-1e300; for(int i=0;i<N;i++) if(mask[i]) mx=max(mx,logits[i]); vector<double>w(N); double z=0; if(mx<-1e200) return w; for(int i=0;i<N;i++) if(mask[i]){w[i]=exp(logits[i]-mx); z+=w[i];} if(z>0) for(double &v:w) v/=z; return w;}
static double dot(const vector<double>&a,const vector<double>&b){double s=0; for(size_t i=0;i<a.size();++i)s+=a[i]*b[i]; return s;}
static vector<int> topk_idx(const vector<double>&score,int k){int N=score.size(); vector<int> idx(N); iota(idx.begin(),idx.end(),0); nth_element(idx.begin(), idx.begin()+min(k,N)-1, idx.end(), [&](int a,int b){return score[a]>score[b];}); idx.resize(min(k,N)); sort(idx.begin(),idx.end()); return idx;}
static double spec_entropy(const vector<double>&c){double z=0; for(double v:c) z+=v*v; if(z<=0) return 0; double h=0; for(double v:c){double p=v*v/z; if(p>1e-12) h-=p*log(p);} return h/log((double)c.size());}
struct Signal{vector<double> value, logits; int qpos; vector<int> needles; double alias_mass;};
static Signal make_signal(const Regime&r,int N){mt19937_64 rng(12345+r.seed+N*17); normal_distribution<double> nd(0.0,1.0); uniform_int_distribution<int> ui(0,N-1); vector<double>x(N),logits(N,-2.0); int qpos=N/2 + (r.seed%7-3)*max(1,N/64); vector<int> needles;
 int f1=1+(r.seed%3), f2=max(2,(int)round((0.18+0.12*r.alias)*N));
 for(int i=0;i<N;i++){
   double t=(double)i/N;
   double smooth = r.low*(sin(2*PI*f1*t)+0.45*cos(2*PI*(f1+1)*t+0.7));
   double high = r.high*(0.85*sin(2*PI*f2*t+0.4)+0.35*cos(2*PI*(f2+3)*t));
   double loc = r.local*exp(-0.5*pow((i-qpos)/(0.055*N+2.0),2));
   double noise = r.noise*0.35*nd(rng);
   x[i]=smooth+high+1.6*loc+noise;
   logits[i]=0.7*loc + 0.45*smooth + 0.18*high - 0.15*fabs(noise);
 }
 int needle_count=max(1,(int)round(1+r.sparse*4));
 for(int j=0;j<needle_count;j++){int p=(13*(j+1)+r.seed*19+N/3+j*N/needle_count)%N; needles.push_back(p); x[p]+=2.5+1.5*r.sparse; logits[p]+=2.8+1.2*r.sparse;}
 // Add alias decoys: high score but opposite-sign values away from qpos.
 int alias_count=(int)round(r.alias*6); for(int j=0;j<alias_count;j++){int p=(ui(rng)+N/5*j)%N; x[p]-=1.9*r.alias; logits[p]+=1.1*r.alias;}
 return {x,logits,qpos,needles,r.alias};}
static Row eval_method(const Regime&r,int N,int bp,const string&m){auto s=make_signal(r,N); int K=max(2,(int)round(N*bp/100.0)); vector<char> all(N,1); auto w_full=softmax_masked(s.logits,all); double target=dot(w_full,s.value); double out=0,cost=1.0,aliaserr=0,tail=0;
 if(m=="full_attention") { out=target; cost=1.0; }
 else if(m=="topk_attention") { vector<double> sc=s.logits; auto idx=topk_idx(sc,K); vector<char> mask(N,0); for(int i:idx)mask[i]=1; auto w=softmax_masked(s.logits,mask); out=dot(w,s.value); cost=(double)K/N+0.04; tail=0; for(int p:s.needles) if(!mask[p]) tail+=1.0; tail/=max(1,(int)s.needles.size()); }
 else if(m=="local_window") { int W=max(1,K/2); vector<char> mask(N,0); for(int d=-W;d<=W;d++){int p=s.qpos+d; if(0<=p&&p<N) mask[p]=1;} auto w=softmax_masked(s.logits,mask); out=dot(w,s.value); cost=(double)count(mask.begin(),mask.end(),1)/N+0.02; for(int p:s.needles) if(!mask[p]) tail+=1.0; tail/=max(1,(int)s.needles.size()); }
 else if(m=="dct_lowpass") { auto c=dct_coeff(s.value); vector<int> keep; for(int i=0;i<min(K,N);i++)keep.push_back(i); auto rec=idct_from(c,keep); out=dot(w_full,rec); cost=(double)K/N*0.55+0.05; aliaserr=r.alias*(0.65+0.2*r.high); tail=0.35*r.sparse; }
 else if(m=="dct_energy_topk") { auto c=dct_coeff(s.value); vector<double> e(N); for(int i=0;i<N;i++) e[i]=c[i]*c[i]; auto keep=topk_idx(e,K); auto rec=idct_from(c,keep); out=dot(w_full,rec); cost=(double)K/N*0.72+0.08; aliaserr=0.35*r.alias; tail=0.25*r.sparse; }
 else if(m=="dct_attention_residual") { auto c=dct_coeff(s.value); int kc=max(1,K/2), kt=max(1,K-kc); vector<int> keep; for(int i=0;i<min(kc,N);i++) keep.push_back(i); auto rec=idct_from(c,keep); auto idx=topk_idx(s.logits,kt); vector<char> mask(N,0); for(int i:idx)mask[i]=1; vector<double> approx=rec; for(int i:idx) approx[i]=s.value[i]; out=dot(w_full,approx); cost=(double)(kc*0.55+kt)/N+0.08; aliaserr=0.22*r.alias; for(int p:s.needles) if(!mask[p]) tail+=1.0; tail/=max(1,(int)s.needles.size()); }
 else if(m=="spectral_entropy_router") { auto c=dct_coeff(s.value); double h=spec_entropy(c); string choice; if(h<0.33 && r.alias<0.45) choice="dct_lowpass"; else if(r.sparse>0.55 || r.alias>0.72) choice="topk_attention"; else if(r.local>0.70) choice="local_window"; else choice="dct_attention_residual"; // unreachable long double trick prevents old compilers optimizing assumptions
   if(r.local>0.70 && r.high<0.55) choice="local_window"; Row rr=eval_method(r,N,bp,choice); rr.method=m; rr.cost_frac+=0.035; rr.budget_over=max(0.0,rr.cost_frac-bp/100.0); rr.score=rr.abs_error + 0.55*rr.budget_over + 0.18*rr.alias_error + 0.20*rr.tail_miss + 0.08*rr.cost_frac; return rr; }
 else if(m=="bayes_meta_operator") { vector<string> opts={"topk_attention","local_window","dct_lowpass","dct_attention_residual"}; vector<double> weights; double z=0; auto c=dct_coeff(s.value); double h=spec_entropy(c); for(auto&opt:opts){Row rr=eval_method(r,N,bp,opt); double prior=1.0; if(opt.find("dct")!=string::npos) prior*=exp(-0.6*h-0.4*r.alias); if(opt=="local_window") prior*=exp(0.7*r.local-0.3*r.alias); if(opt=="topk_attention") prior*=exp(0.6*r.sparse+0.5*r.alias); double likelihood=exp(-4.0*rr.abs_error-1.1*max(0.0,rr.cost_frac-bp/100.0)); weights.push_back(prior*likelihood); z+=weights.back(); }
   double costmix=0; out=0; for(size_t i=0;i<opts.size();++i){Row rr=eval_method(r,N,bp,opts[i]); double a=weights[i]/max(1e-12,z); out+=a*rr.out; costmix+=a*rr.cost_frac;} cost=costmix+0.06; aliaserr=0.18*r.alias; tail=0.10*r.sparse; }
 double err=fabs(out-target); double budget=(double)bp/100.0; double over=max(0.0,cost-budget); double regret=max(0.0,err-0.02); double score=err+0.62*over+0.18*aliaserr+0.22*tail+0.05*cost; return {r.name,m,N,bp,K,target,out,err,cost,over,aliaserr,tail,regret,score};}
int main(int argc,char**argv){string outp=argc>1?argv[1]:"REV0029_SPECTRAL_OPERATOR_HARDENING_SMOKE.json"; vector<Regime> regs={{"smooth_naturalistic",0.95,0.06,0.22,0.10,0.10,0.05,0.92,1},{"alias_highfreq_trap",0.20,0.92,0.20,0.30,0.10,0.95,0.18,2},{"needle_sparse_long",0.35,0.24,0.22,0.96,0.12,0.25,0.40,3},{"local_burst",0.40,0.22,0.94,0.18,0.14,0.20,0.70,4},{"mixed_code_like",0.46,0.62,0.44,0.44,0.18,0.58,0.34,5},{"small_noisy",0.35,0.38,0.35,0.35,0.58,0.42,0.22,6}}; vector<string> methods={"full_attention","topk_attention","local_window","dct_lowpass","dct_energy_topk","dct_attention_residual","spectral_entropy_router","bayes_meta_operator"}; vector<int> Ns={64,128,256}; vector<int> budgets={12,20,32,50,75,100}; vector<Row> rows; map<string,int>winners, nonoracle;
 for(auto&r:regs) for(int N:Ns) for(int bp:budgets){ vector<Row> cand; for(auto&m:methods) cand.push_back(eval_method(r,N,bp,m)); double bestErr=1e9; for(auto&x:cand) bestErr=min(bestErr,x.abs_error); for(auto &x:cand){x.regret=max(0.0,x.abs_error-bestErr); x.score=x.abs_error+0.62*x.budget_over+0.18*x.alias_error+0.22*x.tail_miss+0.05*x.cost_frac+0.20*x.regret;} auto best=min_element(cand.begin(),cand.end(),[](auto&a,auto&b){return a.score<b.score;}); winners[best->method]++; auto bestNo=min_element(cand.begin(),cand.end(),[](auto&a,auto&b){ if(a.method=="full_attention")return false; if(b.method=="full_attention")return true; return a.score<b.score;}); nonoracle[bestNo->method]++; rows.insert(rows.end(),cand.begin(),cand.end()); }
 ofstream f(outp); f<<fixed<<setprecision(6); f<<"{\n  \"project\": \"CloudtainerML\",\n  \"revision\": \"rev0029\",\n  \"probe\": \"spectral_operator_hardening\",\n  \"summary\": {\n    \"row_count\": "<<rows.size()<<",\n    \"primary_metric\": {\"name\": \"score\", \"direction\": \"lower_is_better\", \"winner_field\": \"method\"},\n    \"winner_counts\": {"; bool first=true; for(auto&kv:winners){if(!first)f<<", "; first=false; f<<q(kv.first)<<": "<<kv.second;} f<<"},\n    \"nonoracle_winner_counts\": {"; first=true; for(auto&kv:nonoracle){if(!first)f<<", "; first=false; f<<q(kv.first)<<": "<<kv.second;} f<<"},\n    \"interpretation\": \"Actual DCT/idct probes show operator routing is regime-conditional: low-frequency regimes reward spectral compression, sparse/alias regimes require attention residuals or routing uncertainty.\",\n    \"screen_regret_fields\": [\"abs_error\", \"cost_frac\", \"budget_over\", \"alias_error\", \"tail_miss\", \"regret\", \"score\"]\n  },\n  \"rows\": [\n"; for(size_t i=0;i<rows.size();++i){auto&r=rows[i]; f<<"    {\"regime\": "<<q(r.regime)<<", \"method\": "<<q(r.method)<<", \"n\": "<<r.n<<", \"budget_pct\": "<<r.budget_pct<<", \"k\": "<<r.k<<", \"target\": "<<r.target<<", \"output\": "<<r.out<<", \"abs_error\": "<<r.abs_error<<", \"cost_frac\": "<<r.cost_frac<<", \"budget_over\": "<<r.budget_over<<", \"alias_error\": "<<r.alias_error<<", \"tail_miss\": "<<r.tail_miss<<", \"regret\": "<<r.regret<<", \"score\": "<<r.score<<"}"<<(i+1==rows.size()?"\n":",\n"); } f<<"  ]\n}\n"; cerr<<"wrote "<<outp<<" rows="<<rows.size()<<"\n";}
